```c
void F(int a[], int i, int n) {
    if (i >= n - 1) {
        return;
    }
    for (int j = i; j < n - 1; j++) {
        if (a[j] > a[j + 1]) {
            int temp = a[j];
            a[j] = a[j + 1];
            a[j + 1] = temp;
        }
    }
    F(a, i + 1, n);
}
